create extension if not exists pgcrypto;create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text not null default 'Learner',avatar_url text,timezone text default 'UTC',created_at timestamptz not null default now());create table if not exists learning_progress(user_id uuid primary key references auth.users(id) on delete cascade,xp bigint not null default 0,level integer not null default 1,streak integer not null default 0,longest_streak integer not null default 0,daily_goal integer not null default 30,hearts integer not null default 5,last_active date,updated_at timestamptz not null default now());create table if not exists lesson_progress(user_id uuid references auth.users(id) on delete cascade,lesson_id text not null,status text not null default 'started',score integer not null default 0,attempts integer not null default 0,completed_at timestamptz,updated_at timestamptz not null default now(),primary key(user_id,lesson_id));create table if not exists project_progress(user_id uuid references auth.users(id) on delete cascade,project_id text not null,milestone text not null,status text not null default 'locked',notes text default '',updated_at timestamptz not null default now(),primary key(user_id,project_id,milestone));create table if not exists achievements(user_id uuid references auth.users(id) on delete cascade,achievement_id text not null,unlocked_at timestamptz not null default now(),primary key(user_id,achievement_id));create table if not exists user_settings(user_id uuid primary key references auth.users(id) on delete cascade,theme text default 'system',language text default 'en',email_updates boolean not null default true,public_profile boolean not null default true);create index if not exists lesson_progress_user_idx on lesson_progress(user_id,updated_at desc);create index if not exists project_progress_user_idx on project_progress(user_id,updated_at desc);alter table profiles enable row level security;alter table learning_progress enable row level security;alter table lesson_progress enable row level security;alter table project_progress enable row level security;alter table achievements enable row level security;alter table user_settings enable row level security;create policy "profiles own row" on profiles for all using(auth.uid()=id) with check(auth.uid()=id);create policy "learning progress own row" on learning_progress for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "lesson progress own rows" on lesson_progress for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "project progress own rows" on project_progress for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "achievements own rows" on achievements for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "settings own row" on user_settings for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
